from datetime import date, timedelta
from django.core.management.base import BaseCommand
from django.utils import timezone
from marketing.models import BlogPost, CampaignMetric, EmailCampaign

class Command(BaseCommand):
    help = "Seed FitBite with clearly simulated portfolio data."
    def handle(self, *args, **options):
        now = timezone.now()
        posts = [
            ("10 Healthy Lunch Ideas for Busy Professionals", "10-healthy-lunch-ideas", "Practical healthy lunch ideas for workdays when time is limited.", "healthy food delivery", "healthy lunch delivery, balanced lunch, quick healthy meals", "10 Healthy Lunch Ideas for Busy Professionals | FitBite", "Discover practical lunch ideas for busy professionals and build a more balanced workday meal routine.", "Start with a balanced plate: protein, vegetables and a satisfying source of carbohydrates. Then choose meals that are realistic for your schedule.\n\nFor busy professionals, planning two or three repeatable lunch combinations can reduce decision fatigue. If you use a meal-delivery service, compare menu variety, ingredient transparency and convenience before choosing.", "Healthy lunch ideas for busy professionals"),
            ("Benefits of Eating a Balanced Diet", "benefits-balanced-diet", "Understand the everyday value of variety, balance and practical meal structure.", "balanced diet", "healthy eating benefits, balanced meals, nutrition basics", "Benefits of a Balanced Diet: A Practical Guide | FitBite", "Learn why a balanced diet focuses on variety and consistency rather than extreme food rules.", "A balanced diet is easier to sustain when meals contain a useful mix of protein, vegetables, fruit, whole grains and appropriate fats. The goal of this content is education, not medical advice.\n\nFor a simple routine, start by looking at what your current meals are missing and make one manageable improvement at a time.", "Balanced diet guide"),
            ("Healthy Meal Planning for Beginners", "healthy-meal-planning-beginners", "A beginner-friendly approach to planning healthier meals without overcomplicating the week.", "healthy meal planning", "meal prep for beginners, healthy weekly meals, meal planning tips", "Healthy Meal Planning for Beginners | FitBite", "A simple framework for planning balanced meals, shopping efficiently and reducing weekday friction.", "Begin with the meals you already eat. Pick a few repeatable breakfast, lunch and dinner options, then add variety through vegetables, proteins and sides.\n\nMeal planning is most useful when it fits your actual routine. A plan that is too complex is harder to follow, so keep the first version simple.", "Beginner meal planning"),
            ("How to Choose a Healthy Food Delivery Service", "choose-healthy-food-delivery", "A comparison checklist for people researching healthy meal delivery options.", "healthy food delivery", "healthy meal delivery, diet food delivery, food delivery comparison", "How to Choose a Healthy Food Delivery Service | FitBite", "Compare healthy food delivery services using a practical checklist for menus, convenience and local fit.", "When comparing a healthy food delivery service, look at menu variety, how clearly meals are described, delivery coverage, ordering flexibility and customer support.\n\nSearchers often have different intents: some want a quick lunch, some want fitness meals and others want diet-friendly choices. Good landing pages should answer the specific intent instead of using generic claims.", "Compare meal delivery options"),
            ("Healthy Meals for Fitness Beginners", "healthy-meals-fitness-beginners", "A simple content guide for fitness beginners who want practical meal choices.", "fitness meal delivery", "high protein meals, fitness food, healthy meals for beginners", "Healthy Meals for Fitness Beginners | FitBite", "Explore practical meal ideas for fitness beginners without turning food into complicated rules.", "Fitness beginners can start by making meals more consistent and including a suitable protein source, vegetables and satisfying carbohydrates. Individual nutrition needs vary, so this article stays at a general educational level.\n\nThe marketing lesson is to match content to search intent: someone looking for fitness meal delivery needs different information from someone searching for a quick healthy lunch.", "Explore fitness meal options"),
        ]
        for title, slug, excerpt, keyword, secondary, seo_title, meta, content, alt in posts:
            BlogPost.objects.update_or_create(slug=slug, defaults={"title": title, "excerpt": excerpt, "content": content, "seo_title": seo_title, "meta_description": meta, "primary_keyword": keyword, "secondary_keywords": secondary, "featured_image_alt": alt, "published": True, "published_at": now})

        campaigns = [
            ("01 Welcome", "Welcome Email", "Welcome to FitBite — your healthier routine starts here", "Here’s what to expect from FitBite and your first-meal offer.", "New subscribers", "Introduce the brand and explain the next steps.", "Explore FitBite", 500, 492, 8, 210, 42, 3, 9),
            ("02 Education", "Educational Email", "3 simple ways to make weekday lunches healthier", "Small meal-planning changes can make healthy choices easier.", "New subscribers", "Deliver useful content before asking for a purchase.", "Read the lunch guide", 492, 485, 7, 238, 55, 2, 11),
            ("03 Promotion", "Promotional Email", "Get 20% Off Your First Healthy Meal", "A simple first-meal offer for the FitBite campaign.", "Interested users", "Drive qualified traffic back to the campaign landing page.", "Claim 20% Off", 250, 246, 4, 128, 31, 2, 14),
            ("04 Follow-up", "Follow-up Email", "Still thinking about your first healthy meal?", "A reminder with a clear next step and useful content.", "Interested users", "Recover interested users who did not convert after the first offer email.", "See the offer", 210, 207, 3, 104, 22, 1, 8),
            ("05 Newsletter", "Newsletter", "FitBite Weekly: healthy habits + new ideas", "One useful article, one practical tip and one campaign CTA.", "Customers", "Maintain engagement and encourage repeat action.", "Read this week’s guide", 150, 148, 2, 81, 17, 1, 6),
        ]
        for row in campaigns:
            EmailCampaign.objects.update_or_create(name=row[0], defaults={"email_type": row[1], "subject_line": row[2], "preview_text": row[3], "target_segment": row[4], "objective": row[5], "cta": row[6], "sent_count": row[7], "delivered_count": row[8], "bounced_count": row[9], "opened_count": row[10], "clicked_count": row[11], "unsubscribed_count": row[12], "conversions": row[13], "simulated": True, "sent_at": now})

        sources = ["Organic Search", "Email", "Social Media", "Direct", "Referral"]
        base = {"Organic Search": (180, 140, 16, 34, 8), "Email": (130, 90, 12, 28, 9), "Social Media": (110, 72, 8, 20, 5), "Direct": (90, 58, 6, 14, 4), "Referral": (55, 38, 4, 9, 2)}
        for i in range(7):
            d = date.today() - timedelta(days=i)
            for source in sources:
                visits, landing, forms, cta, conv = base[source]
                CampaignMetric.objects.update_or_create(date=d, source=source, defaults={"website_visits": visits+i*3, "landing_page_visits": landing+i*2, "form_submissions": forms+i%3, "cta_clicks": cta+i%4, "email_clicks": max(1, cta//2), "conversions": conv+i%2, "simulated": True})
        self.stdout.write(self.style.SUCCESS("FitBite demo content seeded successfully. All campaign/analytics numbers are marked simulated."))
